4-//
5-// where CC is the cyclomatic complexity (integer >= 1) and `coverage` is a
6:// fraction in [0, 1]. When coverage is unknown (null), the score is null and
7-// is reported as "N/A".
8-
9-/**
10- * Compute the CRAP score for a single method.
11- *
12- * @param {number} cc        Cyclomatic complexity (>= 1).
13: * @param {number|null} coverage  Statement-coverage fraction in [0, 1], or null.
14: * @returns {number|null}    CRAP score, or null when coverage is unknown.
15- */
16-export function crapScore(cc, coverage) {
17:  if (coverage == null) return null;
18-  const complexity = Number(cc);
19-  const uncovered = 1.0 - coverage;
20-  return complexity * complexity * uncovered * uncovered * uncovered + complexity;
21-}
